from datetime import datetime

class EmailClient:

    def __init__(self, addr, capacity) -> None:
        self.addr = addr
        self.capacity = capacity
        self.inbox = []

    def send_to(self, recv, content, size):
        """Sends an email to the given email address.
        :param recv: The email address of the receiver, str.
        :param content: The content of the email, str.
        :param size: The size of the email, float.
        :return: True if the email is sent successfully, False if the receiver's email box is full.
        """
        if size <= 0:
            return False
        receiver = EmailClient(recv, self.capacity)
        if receiver.is_full_with_one_more_email(size):
            return False
        receiver.inbox.append({'content': content, 'size': size})
        return True

    def fetch(self):
        if not self.inbox:
            return None
        email = self.inbox.pop(0)
        email['state'] = 'read'
        return email

    def is_full_with_one_more_email(self, size):
        """Determines whether the email box is full after adding an email of the given size.
        :param size: The size of the email, float.
        :return: True if the email box is full, False otherwise.
        """
        if size <= 0:
            return False
        current_size = sum((email['size'] for email in self.inbox))
        return current_size + size >= self.capacity

    def get_occupied_size(self):
        total_size = 0.0
        for email in self.inbox:
            if email['size'] is not None and isinstance(email['size'], float):
                total_size += email['size']
        return total_size

    def clear_inbox(self, size):
        occupied_size = self.get_occupied_size()
        if occupied_size <= self.capacity - size:
            return 0
        emails_to_delete = int((occupied_size - (self.capacity - size)) / self.inbox[0]['size'])
        for _ in range(emails_to_delete):
            self.inbox.pop(0)
        return emails_to_delete

